function placeHud(el, canvas, camera, world) {
  if (!el) return;
  var v = world.clone().project(camera);
  var x = (v.x * 0.5 + 0.5) * canvas.clientWidth;
  var y = (-v.y * 0.5 + 0.5) * canvas.clientHeight;
  el.style.left = x + "px";
  el.style.top = y + "px";
}

