function initTracks() {
  var canvas = $("#track-canvas");
  if (!canvas || !canvas.getContext) return;
  var ctx = canvas.getContext("2d");
  var kind = "alpha";
  var t = 0;
  var running = true;

  function drawAlpha() {
    ctx.lineWidth = 6;
    ctx.strokeStyle = "#f4f0e4";
    ctx.lineCap = "round";
    var i;
    for (i = 0; i < 5; i += 1) {
      var y = 36 + i * 32;
      var length = 90 + (i % 3) * 18;
      var grow = Math.min(length, (t * 3 + i * 12) % (length + 40));
      ctx.beginPath();
      ctx.moveTo(28, y);
      ctx.lineTo(28 + grow, y);
      ctx.stroke();
    }
  }

  function drawBeta() {
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = "#dfe7f2";
    var i;
    for (i = 0; i < 6; i += 1) {
      ctx.beginPath();
      var x = 28;
      var y = 30 + i * 26;
      ctx.moveTo(x, y);
      var s;
      for (s = 0; s < 22; s += 1) {
        x += 12;
        y += Math.sin(s * 1.65 + i * 0.7 + t * 0.12) * 9;
        ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
  }

  function drawGamma() {
    ctx.fillStyle = "#f4f0e4";
    var i;
    for (i = 0; i < 9; i += 1) {
      var x = 50 + ((i * 53 + t * 2) % 520);
      var y = 28 + ((i * 71) % 150);
      ctx.beginPath();
      ctx.arc(x, y, 1.6, 0, Math.PI * 2);
      ctx.fill();
      if (i % 3 === 0) {
        ctx.strokeStyle = "rgba(244,240,228,0.45)";
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + 18, y + 10);
        ctx.stroke();
      }
    }
  }

  function frame() {
    ctx.fillStyle = "#11150f";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    if (kind === "alpha") drawAlpha();
    else if (kind === "beta") drawBeta();
    else drawGamma();
    t += 1;
    if (running) requestAnimationFrame(frame);
  }

  $all("[data-track]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      kind = btn.getAttribute("data-track");
    });
  });
  frame();
}

