    var cx = Number(m[1]);
    var cy = Number(m[2]);
    var endX = Number(m[6]);
    var endY = Number(m[7]);
    var startAngle = Math.atan2(Number(m[3]) - cx, cy - Number(m[4]));
    var endAngle = Math.atan2(endX - cx, cy - endY);
    var sweepDeg = (endAngle - startAngle) * 180 / Math.PI;
